const crypto = require('crypto');

// Hash function
function sha256(value) {
  if (!value) return undefined;
  return crypto.createHash('sha256')
    .update(String(value).trim().toLowerCase())
    .digest('hex');
}

// Normalize phone
function normalizePhone(phone) {
  return String(phone || '').replace(/\D/g, '');
}

// Debt → Base Value (as per spec)
function getBaseValue(debt) {
  if (debt >= 50000) return 150;
  if (debt >= 30000) return 100;
  if (debt >= 20000) return 50;
  return 0;
}

// Get incoming data (YOUR STRUCTURE)
const body = $input.first().json.body;
const data = body.customData || {};

// Extract fields
const contactId = data.contact_id || '';
const email = data.email || '';
const phone = normalizePhone(data.phone || '');
const firstName = data.first_name || '';
const lastName = data.last_name || '';
const rawDebt = data.debt_amount || 0;

// IMPORTANT: stage field from your payload
const stage = (data.stage || '').toLowerCase();

// Clean debt
const debt = Number(String(rawDebt).replace(/[^0-9.]/g, ''));

// Base value
const baseValue = getBaseValue(debt);

// Event Mapping
let eventName = "Lead";
let stageKey = "lead";
let stageValue = 0;

if (stage.includes("analysis")) {
  eventName = "AnalysisReady";
  stageKey = "analysis_ready";
  stageValue = 50;
}
else if (stage.includes("pitched")) {
  eventName = "Pitched";
  stageKey = "pitched";
  stageValue = 100;
}
else if (stage.includes("deal")) {
  eventName = "DealComplete";
  stageKey = "deal_complete";
  stageValue = 200;
}
else {
  eventName = "Lead";
  stageKey = "lead";
}

// Total Value
const totalValue = baseValue + stageValue;

// Deduplication ID (DO NOT ADD TIMESTAMP HERE)
const eventId = `lead_${contactId}_${stageKey}`;

// Event Time
const eventTime = Math.floor(Date.now() / 1000);

// Meta CAPI Payload
const capiPayload = {
  data: [{
    event_name: eventName,
    event_time: eventTime,
    event_id: eventId,
    action_source: "system_generated",

    user_data: {
      external_id: contactId,
      em: email ? [sha256(email)] : undefined,
      ph: phone ? [sha256(phone)] : undefined,
      fn: firstName ? [sha256(firstName)] : undefined,
      ln: lastName ? [sha256(lastName)] : undefined
    },

    custom_data: {
      value: totalValue,
      currency: "USD",
      debt_amount: debt,
      stage: stageKey
    }
  }]
};

// Pixel Payload (for browser dedup)
const pixelPayload = {
  event_name: eventName,
  event_id: eventId,
  value: totalValue,
  currency: "USD"
};

// Optional logging (WITH timestamp safely)
const logId = `${eventId}_${Date.now()}`;

return [{
  json: {   
    capiPayload,
    pixelPayload,
    logId
  }
}];
